const firebaseConfig={apiKey:"AIzaSyA89LR9cPidk96OuoyWNmo2ey6-_c1pqVE",authDomain:"sweet-accessories-158cb.firebaseapp.com",projectId:"sweet-accessories-158cb",storageBucket:"sweet-accessories-158cb.firebasestorage.app",messagingSenderId:"484869479734",appId:"1:484869479734:web:b8c98051760fff1edfa797"};firebase.initializeApp(firebaseConfig);const db=firebase.firestore(),auth=firebase.auth(),CACHE_DURATION=3e5;function getCached(e){const t=localStorage.getItem(e);if(!t)return null;const{data:a,timestamp:o}=JSON.parse(t);return Date.now()-o>3e5?(localStorage.removeItem(e),null):a}function setCache(e,t){localStorage.setItem(e,JSON.stringify({data:t,timestamp:Date.now()}))}async function getCollection(e){const t=getCached(e);if(t)return t;const a=await db.collection(e).get(),o=[];return a.forEach(e=>o.push({id:e.id,...e.data()})),setCache(e,o),o}async function getDocument(e,t){const a=await db.collection(e).doc(t).get();return a.exists?{id:a.id,...a.data()}:null}async function addDocument(e,t){const a=await db.collection(e).add({...t,createdAt:firebase.firestore.FieldValue.serverTimestamp()});return localStorage.removeItem(e),a.id}async function updateDocument(e,t,a){await db.collection(e).doc(t).update({...a,updatedAt:firebase.firestore.FieldValue.serverTimestamp()}),localStorage.removeItem(e)}async function deleteDocument(e,t){await db.collection(e).doc(t).delete(),localStorage.removeItem(e)}async function login(e,t){return await auth.signInWithEmailAndPassword(e,t)}async function logout(){await auth.signOut()}auth.onAuthStateChanged(e=>{e?localStorage.setItem("adminUser",JSON.stringify({email:e.email,uid:e.uid})):localStorage.removeItem("adminUser")});